  q.push(createMCQ("Who is traditionally celebrated as history's first actor, stepping out of the Greek chorus in 534 BCE to speak dialogue as a distinct character?", "Thespis", "Aeschylus", "Sophocles", "Thespis introduced spoken impersonation at the City Dionysia festival in Athens, from whose name the word thespian derives.", mcqIdx++));
  q.push(createMCQ("Which Athenian festival held in honor of the god of wine and theater staged the great competitive tragedy trilogies of classical antiquity?", "City Dionysia", "Panathenaea", "Eleusinian Mysteries", "The City Dionysia featured dramatic competitions where playwrights presented three connected tragedies followed by a comedic satyr play.", mcqIdx++));
  q.push(createMCQ("Which tragic Greek playwright wrote the only complete surviving tragic trilogy from antiquity, the Oresteia (Agamemnon, The Libation Bearers, and The Eumenides)?", "Aeschylus", "Euripides", "Aristophanes", "Aeschylus introduced the second actor, expanded dialogue, and explored cosmic justice, generational curses, and the creation of trial by jury.", mcqIdx++));
  q.push(createMCQ("Which Sophoclean tragedy portrays a King of Thebes who unwittingly fulfills a prophecy that he will kill his father and marry his mother?", "Oedipus Rex", "Antigone", "Ajax", "Oedipus Rex (Oedipus Tyrannus) was praised by Aristotle in the Poetics as the supreme exemplar of tragic dramatic structure and recognition (anagnorisis).", mcqIdx++));
