  q.push(createMCQ("Which group of Florentine Renaissance humanists, musicians, and poets sought to revive ancient Greek musical drama, inadvertently inventing opera?", "Florentine Camerata", "Accademia dei Lincei", "Arcadian Academy", "Gathering at the palace of Count Giovanni de' Bardi in the late 16th century, the Camerata developed monody (expressive solo singing over basso continuo).", mcqIdx++));
  q.push(createMCQ("Which Italian master's 1607 opera L'Orfeo, recounting Orpheus's descent into the underworld to rescue Eurydice, is hailed as the first operatic masterwork?", "Claudio Monteverdi", "Jacopo Peri", "Giulio Caccini", "Monteverdi used a large 40-piece orchestra and expressive vocal declamation to establish opera as a profound theatrical art form in Mantua.", mcqIdx++));
  q.push(createMCQ("In which maritime Italian city was the world's first public commercial opera house, the Teatro San Cassiano, opened in 1637?", "Venice", "Florence", "Naples", "The opening of Teatro San Cassiano in Venice democratized opera, shifting it from aristocratic private court entertainment to ticketed public performance.", mcqIdx++));
  q.push(createMCQ("What acrobatic, diamond-pattern-costumed Commedia dell'arte character carries a wooden slapstick and serves as a witty servant?", "Arlecchino (Harlequin)", "Pantalone", "Brighella", "Arlecchino used physical comedy, acrobatic agility, and his slapstick bat to outwit masters and drive comic plots.", mcqIdx++));
  q.push(createNumber("In what year CE did Claudio Monteverdi premiere his milestone opera L'Orfeo at the Ducal Palace of Mantua?", 1607, "CE", "February 1607", "L'Orfeo was first performed on 24 February 1607 during carnival festivities in Mantua, establishing the foundation of classical opera."));

  // Cycle 3: Classical & Bel Canto Opera
  q.push(createMCQ("Which Mozart comic opera features the servant Figaro outwitting his aristocratic master Count Almaviva on his wedding day?", "The Marriage of Figaro", "Don Giovanni", "Cosi fan tutte", "Le Nozze di Figaro premiered in Vienna in 1786, setting Beaumarchais's politically subversive play with dazzling ensemble finales.", mcqIdx++));
  q.push(createMCQ("Which Italian vocal style meaning beautiful singing flourished in the early 19th century, characterized by smooth legato, agile coloratura, and vocal beauty?", "Bel Canto", "Verismo", "Sprechstimme", "Bel canto was perfected by Italian masters Rossini, Bellini, and Donizetti, prioritizing dazzling vocal technique and expressiveness.", mcqIdx++));
  q.push(createMCQ("Which Gaetano Donizetti tragic opera features one of the most famous and difficult coloratura mad scenes in operatic history, Il dolce suono?", "Lucia di Lammermoor", "L'elisir d'amore", "Don Pasquale", "Based on Walter Scott's Scottish novel, Lucia murders her forced husband on their wedding night and hallucinates marrying her true love Edgardo.", mcqIdx++));
