  q.push(createMCQ("What was the historical term for male singers castrated before puberty to preserve their high soprano or alto vocal range with adult lung capacity?", "Castrati", "Countertenors", "Falsettos", "Castrati like Farinelli were the international rock stars of 18th-century Baroque opera, possessing astonishing breath control and vocal power.", mcqIdx++));
