  q.push(createMCQ("What dramatic theater term refers to the imaginary invisible barrier separating the performers onstage from the audience in the auditorium?", "The Fourth Wall", "The Proscenium Arch", "The Apron", "Realist theater emphasized maintaining the fourth wall, whereas modernist playwrights like Brecht intentionally broke it to engage the audience critically.", mcqIdx++));
